'use strict';

const fs = require('fs');

function main() {
  const data = fs.readFileSync(0, 'utf8');
  const len = data.length;

  // ---- fast tokenization of all non-negative integers ----
  const maxTokens = ((len + 1) >> 1) + 2;
  const arr = new Int32Array(maxTokens);
  let acount = 0;
  let i = 0;
  while (i < len) {
    let c = data.charCodeAt(i);
    if (c < 48 || c > 57) { i++; continue; }
    let val = 0;
    while (i < len) {
      c = data.charCodeAt(i);
      if (c >= 48 && c <= 57) { val = val * 10 + (c - 48); i++; }
      else break;
    }
    if (acount < maxTokens) arr[acount++] = val;
  }

  if (acount < 2) { process.stdout.write('-1\n'); return; }

  const N = arr[0];
  const M = arr[1];

  // ---- DSU ----
  const parent = new Int32Array(N + 1);
  const sz = new Int32Array(N + 1);
  for (let v = 0; v <= N; v++) { parent[v] = v; sz[v] = 1; }

  function find(x) {
    let r = x;
    while (parent[r] !== r) r = parent[r];
    while (parent[x] !== r) { const t = parent[x]; parent[x] = r; x = t; }
    return r;
  }

  const ea = new Int32Array(M);
  const eb = new Int32Array(M);
  let m = 0;
  {
    let p = 2;
    while (m < M && p + 2 <= acount) {
      ea[m] = arr[p]; eb[m] = arr[p + 1];
      p += 2; m++;
    }
  }

  for (let e = 0; e < m; e++) {
    const rx = find(ea[e]), ry = find(eb[e]);
    if (rx !== ry) {
      if (sz[rx] < sz[ry]) { parent[rx] = ry; sz[ry] += sz[rx]; }
      else { parent[ry] = rx; sz[rx] += sz[ry]; }
    }
  }

  const deg = new Int32Array(N + 1);
  for (let e = 0; e < m; e++) { deg[ea[e]]++; deg[eb[e]]++; }

  // edges inside each component
  const compEdges = new Int32Array(N + 1);
  for (let e = 0; e < m; e++) compEdges[find(ea[e])]++;

  // ---- adjacency lists (linked lists over arrays) ----
  const headAdj = new Int32Array(N + 1).fill(-1);
  const nxtAdj = new Int32Array(2 * m);
  const toAdj = new Int32Array(2 * m);
  let ecnt = 0;
  for (let e = 0; e < m; e++) {
    const x = ea[e], y = eb[e];
    toAdj[ecnt] = y; nxtAdj[ecnt] = headAdj[x]; headAdj[x] = ecnt; ecnt++;
    toAdj[ecnt] = x; nxtAdj[ecnt] = headAdj[y]; headAdj[y] = ecnt; ecnt++;
  }

  // ---- bucket vertices by component root ----
  const rootOf = new Int32Array(N + 1);
  const cntArr = new Int32Array(N + 2);
  for (let v = 1; v <= N; v++) {
    const r = find(v);
    rootOf[v] = r;
    cntArr[r]++;
  }
  const start = new Int32Array(N + 2);
  let acc = 0;
  for (let r = 1; r <= N; r++) { start[r] = acc; acc += cntArr[r]; }
  const posArr = start.slice();
  const order = new Int32Array(N);
  for (let v = 1; v <= N; v++) order[posArr[rootOf[v]]++] = v;

  // ---- find a pair in the same component without a direct edge ----
  const stamp = new Int32Array(N + 1);
  let token = 0;
  let ansA = -1, ansB = -1;

  for (let r = 1; r <= N && ansA === -1; r++) {
    if (rootOf[r] !== r) continue;
    const s = sz[r];
    if (s < 2) continue;
    if (2 * compEdges[r] >= s * (s - 1)) continue; // component is already a clique

    const lo = start[r], hi = lo + cntArr[r];

    // vertex of minimum degree inside the component
    let v = order[lo], best = deg[v];
    for (let k = lo + 1; k < hi; k++) {
      const u = order[k];
      if (deg[u] < best) { best = deg[u]; v = u; }
    }

    // mark neighbors of v
    token++;
    for (let ei = headAdj[v]; ei !== -1; ei = nxtAdj[ei]) stamp[toAdj[ei]] = token;

    // some vertex in the same component is NOT adjacent to v (guaranteed, since
    // min degree < s-1 when the component is not complete)
    for (let k = hi - 1; k >= lo; k--) {
      const u = order[k];
      if (u !== v && stamp[u] !== token) {
        ansA = v < u ? v : u;
        ansB = v < u ? u : v;
        break;
      }
    }
  }

  if (ansA === -1) process.stdout.write('-1\n');
  else process.stdout.write(ansA + ' ' + ansB + '\n');
}

main();
